import * as THREE from 'three';

import { Addon } from './';
import { loadFBXWithMat } from '../../../../../utils/ThreeUtils';

export class LaserDevice {
	public addon: Addon;

	private mesh: THREE.Group;
	private laserDevices: LaserDeviceItem[] = [];

	constructor(addon: Addon) {
		this.addon = addon;
		this.mesh = new THREE.Group();
		this.mesh.name = 'LaserDevice';
		this.mesh.userData = { obj: this };
		this.loadSolarPanel([addon.hypercubeParametric.configurator.BASE_URL + 'LaserDevice.fbx'], 0.25);
	}
	private loadSolarPanel = async (files, scale) => {
		try {
			const loadPromises = files.map((file) =>
				loadFBXWithMat(
					file,
					scale,
					this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
					this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
					this.addon.hypercubeParametric.configurator.materials.clippingPlanes,
					this.addon.hypercubeParametric.configurator.materials.MaterialClass,
					this.addon.hypercubeParametric.configurator.materials.addonMaterial
				)
			);

			const fbxModels = await Promise.all(loadPromises);
			fbxModels[0].rotation.z = -Math.PI * 0.5;
			fbxModels[0].position.y = -0.3;
			// this.mesh.add(fbxModels[0]);

			for (let i = 0; i < 3; ++i) {
				const ddd = new LaserDeviceItem(this, i, fbxModels[0].clone(true));
				ddd.mesh.position.x = i * 10;
				this.laserDevices.push(ddd);
			}

			// const clonedMesh = fbxModels[0].clone(true);
			// clonedMesh.position.x += 12;
			// this.mesh.add(clonedMesh);

			// this.appendLaser();

			// this.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh);
			this.syncSizes();
		} catch (error) {
			console.error('fail to load :', error);
		}
	};
	public syncSizes() {
		this.laserDevices.forEach((item: LaserDeviceItem) => {
			item.syncSizes();
		});
	}
	public toggleVisibility() {
		this.laserDevices.forEach((item: LaserDeviceItem) => {
			item.toggleVisibility();
		});
	}
}

export class LaserDeviceItem {
	public host: LaserDevice;

	public mesh: THREE.Group;
	private meshLaser: THREE.Mesh;

	public id = 0;

	constructor(host: LaserDevice, id: number, model: LaserDevice) {
		this.id = id;
		this.host = host;
		this.mesh = new THREE.Group();
		this.mesh.userData = { obj: this };
		this.loadSolarPanel(model);
	}
	private loadSolarPanel = async (model) => {
		model.rotation.z = -Math.PI * 0.5;
		model.position.y = -0.3;
		this.mesh.add(model);

		// const clonedMesh = fbxModels[0].clone(true);
		// clonedMesh.position.x += 12;
		// this.mesh.add(clonedMesh);

		this.appendLaser();

		this.host.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh);
		this.syncSizes();

		// const fbxModels = await Promise.all(loadPromises);
		// fbxModels[0].rotation.z = -Math.PI * 0.5;
		// fbxModels[0].position.y = -0.3;

		// this.mesh.add(fbxModels[0]);
		// this.appendLaser();

		// this.host.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh);
		// this.syncSizes();
	};
	private appendLaser() {
		const radius = 0.5;
		const height = 3.5;
		const geometry = new THREE.CylinderGeometry(radius, radius, height, 32);

		geometry.translate(0.0, height * 0.25, 0.0);
		const material = this.host.addon.hypercubeParametric.configurator.materials.laserBarrelMaterial;

		const laserOffsetZ = 1.0;
		const laserOffsetY = 2.4;
		this.meshLaser = new THREE.Mesh(geometry, material);
		this.meshLaser.position.z = laserOffsetZ;
		this.meshLaser.position.y = laserOffsetY;
		// this.host.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.meshLaser);

		this.updateAngle();
		this.mesh.add(this.meshLaser);
	}
	public syncSizes() {
		if (this.mesh) {
			if (this.id === 0) {
				this.mesh.position.x = -this.host.addon.hypercubeParametric.params.width * 0.5 + this.host.addon.hypercubeParametric.params.thickness * 0.5;
				this.mesh.position.z = this.host.addon.hypercubeParametric.params.length * 0.5 - this.host.addon.hypercubeParametric.params.thickness * 0.5;
			} else if (this.id === 1) {
				this.mesh.position.x = -this.host.addon.hypercubeParametric.params.width * 0.5 + this.host.addon.hypercubeParametric.params.thickness * 0.5;
				this.mesh.position.z = -this.host.addon.hypercubeParametric.params.length * 0.5 + this.host.addon.hypercubeParametric.params.thickness * 0.5;
			} else if (this.id === 2) {
				this.mesh.position.x = this.host.addon.hypercubeParametric.params.width * 0.5 - this.host.addon.hypercubeParametric.params.thickness * 0.5;
				this.mesh.position.z = -this.host.addon.hypercubeParametric.params.length * 0.5 + this.host.addon.hypercubeParametric.params.thickness * 0.5;
			}

			this.mesh.position.y = this.host.addon.hypercubeParametric.params.height + this.host.addon.hypercubeParametric.params.groundY;
		}
	}
	public updateRotation(degree: number = 1.4) {
		this.mesh.rotation.y = degree;
	}
	public updateAngle(degree: number = 1.4) {
		const clampedDegree = THREE.MathUtils.clamp(degree, 1, 2);
		this.meshLaser.rotation.x = clampedDegree; // THREE.MathUtils.degToRad(clampedDegree);
	}
	public toggleVisibility() {
		this.mesh.visible = !this.mesh.visible;
	}
}
