import * as THREE from 'three';

import { AppCore } from '..';
import { CLICK_TYPE, ENVIRONMENT_TYPE } from '../../utils/const';
import { HypercubePopup } from './HypercubePopup';

export class ActiveCommand {
	public appCore: AppCore;

	public selectedMesh: THREE.Object3D | undefined = undefined;
	public hoverMesh: THREE.Object3D | undefined = undefined;

	public popup: HypercubePopup;

	private isHoverNewMesh = false;

	constructor(appCore: AppCore) {
		this.appCore = appCore;
		this.popup = new HypercubePopup(this.appCore.rendererCore.host)
	}
	public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
		if (type === CLICK_TYPE.LEFT) {
			this.mouseLeftClickPre(e);
			this.appCore.sceneWrapper.renderForce();
			return;
		} else if (type === CLICK_TYPE.MIDDLE) {
			this.mouseMiddleClickPre(e);
			return;
		} else if (type === CLICK_TYPE.DOWN_RIGHT) {
			this.mouseRightClickPre(e);
			this.appCore.sceneWrapper.renderForce();
			return;
		} else if (type === CLICK_TYPE.DOUBLE) {
			this.mouseDoubleClickPre(e);
			this.appCore.sceneWrapper.renderForce();
			return;
		} else if (type === CLICK_TYPE.MOVE) {
			this.mouseMovePre(e);
			return;
		} else if (type === CLICK_TYPE.DRAG) {
			this.mouseDragPre(e);
			this.appCore.sceneWrapper.renderForce();
			return;
		} else if (type === CLICK_TYPE.DOWN) {
			this.mouseDownPre(e);
			this.appCore.sceneWrapper.renderForce();
			return;
		} else if (type === CLICK_TYPE.WHEEL) {
			this.mouseWheelPre(e);
			this.appCore.sceneWrapper.renderForce();
			return;
		} else if (type === CLICK_TYPE.UP) {
			this.mouseUpPre(e);
			return;
		}
	}
	public mouseDown(e: MouseEvent) {
		/* */
	}
	public mouseDownPre(e: MouseEvent) {
		this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerDown(e as PointerEvent);

		this.mouseDown(e);
	}
	public mouseLeftClick(e: MouseEvent) {
		const mesh = picking(this.appCore.rendererCore.host, this.appCore.rendererCore.cameraWrapper.camera, this.appCore.rendererCore.scene, e);
		// console.log('click', mesh.name, mesh);
		// console.log(mesh.geometry, mesh.material);
		this.selectedMesh = mesh;

		// if (this.appCore.sceneWrapper.environmentType === ENVIRONMENT_TYPE.) {
			const pop = updatePopupPosition(this.appCore.rendererCore.cameraWrapper.camera, this.selectedMesh, this.appCore.rendererCore.renderer)
			if (pop) {
				this.popup.updatePos(pop)
			}
			// console.log(mesh.name, e, "core");

			if (mesh.name === 'mesh11848' || mesh.name === 'Object991') {
				this.appCore.sceneWrapper.hyperCube.clickDoorInner();
			}
			if (mesh.name === 'Object981') {
				this.appCore.sceneWrapper.hyperCube.clickDoorOuter();
			}
			if (mesh.name === 'Object984') {
				this.appCore.sceneWrapper.hyperCube.showCamera();
			}
			if (mesh.name === 'Object987') {
				this.appCore.sceneWrapper.hyperCube.showGraph();
			}
			if (mesh.name === 'Object996') {
				this.appCore.sceneWrapper.hyperCube.showGraphDrone();
			}

			if (this.appCore.sceneWrapper.configurator && this.selectedMesh && this.selectedMesh.name.includes('rolling')) {
				this.appCore.common.commandHypercubeParametric.openSelectedRollingDoor(this.selectedMesh.name);
			}
			if (this.appCore.sceneWrapper.configurator && this.selectedMesh && this.selectedMesh.name.includes('sliding')) {
				this.appCore.common.commandHypercubeParametric.openSelectedSlidingDoor(this.selectedMesh.name);
			}
		// }
	}
	public mouseLeftClickPre(e: MouseEvent) {
		// console.log("left click");

		this.mouseLeftClick(e);
	}
	public MouseMiddleClick(e: MouseEvent) {
		/* */
	}
	public mouseMiddleClickPre(e: MouseEvent) {
		this.MouseMiddleClick(e);
	}
	public MouseRightClick(e: MouseEvent) {
		/* */
	}
	public mouseRightClickPre(e: MouseEvent) {
		this.MouseRightClick(e);
	}
	public mouseUp(e: MouseEvent) {
		/* */
	}
	public mouseUpPre(e: MouseEvent) {
		this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerUp();
		this.mouseUp(e);
	}
	public mouseDoubleClick(e: MouseEvent) {
		/* */
	}
	public mouseDoubleClickPre(e: MouseEvent) {
		// console.log("d click");
		this.mouseDoubleClick(e);
	}
	public mouseMove(e: MouseEvent) {
		/* */
	}
	public mouseMovePre(e: MouseEvent) {
		this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerMove(e as PointerEvent);


		if (this.appCore.sceneWrapper.environmentType === ENVIRONMENT_TYPE.Configurator) {
			const mesh = picking(this.appCore.rendererCore.host, this.appCore.rendererCore.cameraWrapper.camera, this.appCore.rendererCore.scene, e);
			
			if (this.hoverMesh && this.hoverMesh.name === mesh.name) {
				
				if (this.isHoverNewMesh) {
					// console.log('move', this.hoverMesh.name, this.hoverMesh);
					this.appCore.common.updateTooltip(this.hoverMesh.name)
					this.isHoverNewMesh = false
				}
				
			} else {
				this.appCore.common.closeTooltip()
					this.isHoverNewMesh = true
			}

			this.hoverMesh = mesh;
		
		}
		
		// this.updatePopupPos()

		this.mouseMove(e);
	}
	public mouseDrag(e: MouseEvent) {
		/* */
	}
	public mouseDragPre(e: MouseEvent) {
		// console.log("drag");
		this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerMove(e as PointerEvent);

		this.updatePopupPos()


		this.mouseDrag(e);
	}
	public mouseWheel(e: MouseEvent) {
		/* */
	}
	public mouseWheelPre(e: MouseEvent) {
		// console.log("drag");
		this.mouseWheel(e);
	}

	public updatePopupPos = () => {
		if (this.selectedMesh){
			// console.log(['updating'])
			const pop = updatePopupPosition(this.appCore.rendererCore.cameraWrapper.camera, this.selectedMesh, this.appCore.rendererCore.renderer)
			this.popup.updatePos(pop)
		}
	}
}

const updatePopupPosition = (camera, selectedObject, renderer) => {
	// debugger
	if (!selectedObject) return
	
	const box = new THREE.Box3().setFromObject(selectedObject);
	const center = new THREE.Vector3();
	box.getCenter(center);
	
	const projected = center.clone().project(camera);
	
	//   if (projected.z > 1) {
	//     popup.style.opacity = '0';
	//     return;
	//   }
	
	const canvas = renderer.domElement;
	const rect = canvas.getBoundingClientRect();
	
	const x = (projected.x * 0.5 + 0.5) * rect.width;
	const y = (-projected.y * 0.5 + 0.5) * rect.height;
	
	return [x, y, projected.z];
}

const picking = (div: HTMLElement, camera: THREE.PerspectiveCamera, scene: THREE.Scene, event: MouseEvent) => {
	const raycaster = new THREE.Raycaster();
	const mouse = new THREE.Vector2();
	const rect = div.getBoundingClientRect();

	mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
	mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

	raycaster.setFromCamera(mouse, camera);

	const intersects = raycaster.intersectObjects(scene.children, true);
	const isFullyVisible = (object: THREE.Object3D): boolean => {
		let current: THREE.Object3D | null = object;
		while (current) {
			if (!current.visible) return false;
			current = current.parent;
		}
		return true;
	};

	const visibleIntersects = intersects.filter((i) => isFullyVisible(i.object));
	// console.log(visibleIntersects);
	if (visibleIntersects.length > 0) {
		const selectedObject = visibleIntersects[0].object;
		// console.log('Selected object:', selectedObject);
		// console.log('Name:', selectedObject.name);
		// console.log("position:", selectedObject.position);
		// console.log("scale:", selectedObject.scale);
		// console.log("Material:", selectedObject.material);
		// selectedObject.position.y += 100;

		if (selectedObject.name === 'ground') {
			return undefined;
		}
		return selectedObject;
	} else {
		// console.log("noting selected");
		return undefined;
	}
};
