import { ENVIRONMENT_TYPE } from '../../utils/const';
import { AppCommon } from './';

export class APIHypercube {
	public common: AppCommon;
	constructor(common: AppCommon) {
		this.common = common;
	}
	public shiftEnvironmentType(type: ENVIRONMENT_TYPE) {
		this.common.commonSandbox.hideAll();

		console.log(type)
		
		switch (type) {
			case ENVIRONMENT_TYPE.Substation:
				this.common.commonSandbox.showSubstation();
				break;

			case ENVIRONMENT_TYPE.SubstationDiorama:
				this.common.commonSandbox.showSubstationDiorama();
				break;

			default:
				this.common.commonSandbox.showStudioEnv();
				break;
		}
	}
}
