import * as THREE from 'three';

import { Configurator } from '..';

export class ClippingController {
	public configurator: Configurator;
	public isActivated: boolean = false;

	public planeX: THREE.Mesh;
	public planeY: THREE.Mesh;
	public planeZ: THREE.Mesh;

	public clippingPlanes = [];

	constructor(configurator: Configurator) {
		this.configurator = configurator;

		const size = 60;
		const planeGeometry = new THREE.PlaneGeometry(size, size);
		const planeMaterial = new THREE.MeshBasicMaterial({
			color: 0x000000,
			opacity: 0.05,
			transparent: true,
			side: THREE.DoubleSide,
		});

		this.planeY = new THREE.Mesh(planeGeometry, planeMaterial);
		this.planeY.castShadow = false;
		this.planeY.receiveShadow = false;

		this.planeY.rotateX(Math.PI / 2);
		this.configurator.sceneWrapper.scene.add(this.planeY);

		this.planeX = new THREE.Mesh(planeGeometry, planeMaterial);
		this.planeX.castShadow = false;
		this.planeX.receiveShadow = false;
		this.planeX.rotateY(Math.PI / 2);
		this.configurator.sceneWrapper.scene.add(this.planeX);

		this.planeZ = new THREE.Mesh(planeGeometry, planeMaterial);
		this.planeZ.castShadow = false;
		this.planeZ.receiveShadow = false;
		this.configurator.sceneWrapper.scene.add(this.planeZ);

		this.bindClippingMaterial();
		this.toggleMode();
	}
	private bindClippingMaterial() {
		this.clippingPlanes = this.configurator.materials.clippingPlanes;

		this.updateXClipping(30);
		this.updateYClipping(30);
		this.updateZClipping(30);
	}
	// public updateScale() {
	// 	const sizeX = this.configurator.hypercubeParametric.params.width * 2;
	// 	const sizeY = this.configurator.hypercubeParametric.params.height * 2;
	// 	const sizeZ = this.configurator.hypercubeParametric.params.length * 2;
	// 	this.planeX.scale.set(sizeX, sizeX, sizeX);
	// 	this.planeY.scale.set(sizeY, sizeY, sizeY);
	// 	this.planeZ.scale.set(sizeZ, sizeZ, sizeZ);
	// }
	public updateYClipping(value: number) {
		this.clippingPlanes[0].constant = value;
		this.planeY.position.y = value;
	}
	public updateXClipping(value: number) {
		this.clippingPlanes[1].constant = value;
		this.planeX.position.x = value;
	}
	public updateZClipping(value: number) {
		this.clippingPlanes[2].constant = value;
		this.planeZ.position.z = value;
	}
	public toggleMode() {
		this.planeX.visible = !this.planeX.visible;
		this.planeY.visible = !this.planeY.visible;
		this.planeZ.visible = !this.planeZ.visible;
	}
}
