export class NVector3 {
	x: number = 0.0;
	y: number = 0.0;
	z: number = 0.0;
	w: number = 0.0;
	long: number = 0.0;
	lat: number = 0.0;
	ele: number = 0.0;
	proX: number = 0.0;
	proY: number = 0.0;
	proZ: number = 0.0;
	alt: number = 0.0;

	static Origin(): NVector3 {
		return new NVector3(0, 0, 0);
	}
	constructor(x: number, y: number, z: number = 0) {
		this.x = x;
		this.y = y;
		this.z = z;
	}
	Mult(v: number): NVector3 {
		this.x *= v;
		this.y *= v;
		this.z *= v;
		return new NVector3(this.x, this.y, this.z);
	}
	Unitize(): NVector3 {
		return this.Normalize();
	}
	Normalize(): NVector3 {
		let len: number = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
		this.x = this.x / len;
		this.y = this.y / len;
		this.z = this.z / len;
		return new NVector3(this.x, this.y, this.z);
	}
}

export class NSolarRobust {
	public static Radians(degrees: number): number {
		return degrees * (3.14159265358979 / 180.0);
	}

	public static Degrees(radians: number): number {
		return radians * (180.0 / 3.14159265358979);
	}
	public VectorOrigin: NVector3 = NVector3.Origin();
	public VectorSun: NVector3 = NVector3.Origin();
	public SunPoint: NVector3;

	public declination: number = 0;
	public solarAltitude: number = 0;
	public solarAzimuth: number = 0;
	public hourAngle: number = 0;

	public southDegree: number = 180;
	public sunDistance: number = 100;
	public SphereRadius: number = 10.0;

	public year: number = -1;
	public month: number = -1;
	public day: number = 1;
	public latitude: number = 42.3;
	public longitude: number = 0;
	public hour: number = 14;
	public minute: number = 0;
	public timezone: number = 0;

	constructor() {}
	public update(latitude: number, longitude: number, year: number, month: number, day: number, hour: number, minute: number = 0, sunDistance: number = 100, sphereSize: number = 10.0) {
		this.day = this.CalculateDayOfYear(year, month, day);
		this.month = month;
		this.year = year;
		this.latitude = latitude;
		this.longitude = longitude;
		this.hour = hour;
		this.minute = minute;

		this.timezone = this.GetTimezoneFromCoordinates(latitude, longitude);

		this.sunDistance = sunDistance;
		this.SphereRadius = sphereSize;

		this.declination = this.CalculateDeclination(this.day);
		this.hourAngle = this.CalculateHourAngle(this.hour, this.minute, this.longitude, this.timezone);

		this.solarAltitude = this.CalculateSolarAltitude(this.latitude, this.declination, this.hourAngle);
		this.solarAzimuth = this.CalculateSolarAzimuth(this.latitude, this.declination, this.hourAngle, this.solarAltitude);

		this.CalculateSunVector();
	}
	private CalculateDayOfYear(year: number, month: number, day: number): number {
		const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

		if (this.isLeapYear(year)) {
			daysInMonth[1] = 29;
		}

		let dayOfYear = 0;
		for (let i = 0; i < month - 1; i++) {
			dayOfYear += daysInMonth[i];
		}
		dayOfYear += day;

		return dayOfYear;
	}
	private isLeapYear(year: number): boolean {
		return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
	}
	private GetTimezoneFromCoordinates(latitude: number, longitude: number): number {
		let timezone = Math.round(longitude / 15);

		if (this.IsInChina(latitude, longitude)) {
			return 8; // china  UTC+8
		} else if (this.IsInIndia(latitude, longitude)) {
			return 5.5; // India UTC+5:30
		} else if (this.IsInRussia(latitude, longitude)) {
			return this.GetRussianTimezone(longitude);
		} else if (this.IsInAustralia(latitude, longitude)) {
			return this.GetAustralianTimezone(latitude, longitude);
		} else if (this.IsInUSA(latitude, longitude)) {
			return this.GetUSATimezone(longitude);
		} else if (this.IsInCanada(latitude, longitude)) {
			return this.GetCanadaTimezone(longitude);
		} else if (this.IsInBrazil(latitude, longitude)) {
			return this.GetBrazilTimezone(longitude);
		} else if (this.IsInEurope(latitude, longitude)) {
			return this.GetEuropeanTimezone(longitude);
		}

		if (longitude >= -180 && longitude < -157.5 && latitude >= 18.9 && latitude <= 28.4) {
			return -10; // hawaii
		}
		if (longitude >= -179 && longitude <= 179 && latitude >= -25 && latitude <= -8) {
			return 12; // Fiji/New Zealand
		}

		return Math.max(-12, Math.min(14, timezone));
	}

	private IsInChina(lat: number, lng: number): boolean {
		return lat >= 18 && lat <= 54 && lng >= 73 && lng <= 135;
	}

	private IsInIndia(lat: number, lng: number): boolean {
		return lat >= 6 && lat <= 37 && lng >= 68 && lng <= 97;
	}

	private IsInRussia(lat: number, lng: number): boolean {
		return lat >= 41 && lat <= 82 && lng >= 19 && lng <= 180;
	}

	private GetRussianTimezone(lng: number): number {
		if (lng < 30) return 3; // Moscow Time
		if (lng < 45) return 4; // Samara Time
		if (lng < 60) return 5; // Yekaterinburg Time
		if (lng < 75) return 6; // Omsk Time
		if (lng < 90) return 7; // Krasnoyarsk Time
		if (lng < 105) return 8; // Irkutsk Time
		if (lng < 120) return 9; // Yakutsk Time
		if (lng < 135) return 10; // Vladivostok Time
		if (lng < 150) return 11; // Magadan Time
		return 12; // Kamchatka Time
	}

	private IsInAustralia(lat: number, lng: number): boolean {
		return lat >= -44 && lat <= -10 && lng >= 112 && lng <= 154;
	}

	private GetAustralianTimezone(lat: number, lng: number): number {
		if (lng < 127.5) return 8; // Western Australia (AWST)
		if (lng < 137.5) return 9.5; // Central Australia (ACST)
		return 10; // Eastern Australia (AEST)
	}

	private IsInUSA(lat: number, lng: number): boolean {
		return lat >= 18.9 && lat <= 71.4 && lng >= -180 && lng <= -66;
	}

	private GetUSATimezone(lng: number): number {
		if (lng > -75) return -5; // Eastern Time (EST)
		if (lng > -90) return -6; // Central Time (CST)
		if (lng > -105) return -7; // Mountain Time (MST)
		if (lng > -125) return -8; // Pacific Time (PST)
		if (lng > -140) return -9; // Alaska Time (AKST)
		return -10; // Hawaii-Aleutian Time (HST)
	}

	private IsInCanada(lat: number, lng: number): boolean {
		return lat >= 41.7 && lat <= 83.1 && lng >= -141 && lng <= -52;
	}

	private GetCanadaTimezone(lng: number): number {
		if (lng > -60) return -4; // Atlantic Time
		if (lng > -70) return -5; // Eastern Time
		if (lng > -90) return -6; // Central Time
		if (lng > -105) return -7; // Mountain Time
		if (lng > -125) return -8; // Pacific Time
		if (lng > -135) return -9; // Yukon Time
		return -8; // Default
	}

	private IsInBrazil(lat: number, lng: number): boolean {
		return lat >= -34 && lat <= 5.3 && lng >= -74 && lng <= -32;
	}

	private GetBrazilTimezone(lng: number): number {
		if (lng > -38) return -3; // Brasília Time
		if (lng > -52) return -3; // Brasília Time
		if (lng > -68) return -4; // Amazon Time
		return -5; // Acre Time
	}

	private IsInEurope(lat: number, lng: number): boolean {
		return lat >= 35 && lat <= 71 && lng >= -25 && lng <= 45;
	}

	private GetEuropeanTimezone(lng: number): number {
		if (lng < 7.5) return 0; // Western European Time (GMT)
		if (lng < 22.5) return 1; // Central European Time (CET)
		return 2; // Eastern European Time (EET)
	}
	private CalculateDeclination(dayOfYear: number): number {
		const angle = (2 * Math.PI * (dayOfYear - 81)) / 365;
		return 23.45 * Math.sin(angle);
	}

	private CalculateHourAngle(hour: number, minute: number, longitude: number, timezone: number): number {
		const localTime = hour + minute / 60;
		const solarTime = localTime + longitude / 15 - timezone;
		return (solarTime - 12) * 15;
	}

	private CalculateSolarAltitude(latitude: number, declination: number, hourAngle: number): number {
		const latRad = NSolarRobust.Radians(latitude);
		const decRad = NSolarRobust.Radians(declination);
		const hourRad = NSolarRobust.Radians(hourAngle);

		const sinAltitude = Math.sin(latRad) * Math.sin(decRad) + Math.cos(latRad) * Math.cos(decRad) * Math.cos(hourRad);

		return NSolarRobust.Degrees(Math.asin(Math.max(-1, Math.min(1, sinAltitude))));
	}
	private CalculateSolarAzimuth(latitude: number, declination: number, hourAngle: number, altitude: number): number {
		const latRad = NSolarRobust.Radians(latitude);
		const decRad = NSolarRobust.Radians(declination);
		const hourRad = NSolarRobust.Radians(hourAngle);
		const altRad = NSolarRobust.Radians(altitude);

		const cosAzimuth = (Math.sin(decRad) - Math.sin(altRad) * Math.sin(latRad)) / (Math.cos(altRad) * Math.cos(latRad));

		let azimuth = NSolarRobust.Degrees(Math.acos(Math.max(-1, Math.min(1, cosAzimuth))));

		if (hourAngle > 0) {
			azimuth = 360 - azimuth;
		}

		return azimuth;
	}
	private CalculateSunVector(): void {
		const altRad = NSolarRobust.Radians(this.solarAltitude);
		const azRad = NSolarRobust.Radians(this.solarAzimuth);

		this.VectorSun.x = Math.cos(altRad) * Math.sin(azRad);
		this.VectorSun.y = Math.cos(altRad) * Math.cos(azRad);
		this.VectorSun.z = Math.sin(altRad);

		this.VectorSun.Unitize();

		this.SunPoint = this.VectorSun.Mult(this.sunDistance);
	}
	public IsSunAboveHorizon(): boolean {
		return this.solarAltitude > 0;
	}

	public CalculateSunrise(): number {
		const latRad = NSolarRobust.Radians(this.latitude);
		const decRad = NSolarRobust.Radians(this.declination);

		const cosHourAngle = -Math.tan(latRad) * Math.tan(decRad);

		if (Math.abs(cosHourAngle) > 1) {
			return NaN; // Polar night or Midnight sun
		}

		const hourAngle = NSolarRobust.Degrees(Math.acos(cosHourAngle));
		return 12 - hourAngle / 15;
	}
	public CalculateSunset(): number {
		const latRad = NSolarRobust.Radians(this.latitude);
		const decRad = NSolarRobust.Radians(this.declination);

		const cosHourAngle = -Math.tan(latRad) * Math.tan(decRad);

		if (Math.abs(cosHourAngle) > 1) {
			return NaN; // Polar night or Midnight sun
		}

		const hourAngle = NSolarRobust.Degrees(Math.acos(cosHourAngle));
		return 12 + hourAngle / 15;
	}
	public GetSolarInfo(): string {
		return `Solar Position Info:
        Day of Year: ${this.day}
        Latitude: ${this.latitude.toFixed(2)}°
        Longitude: ${this.longitude.toFixed(2)}°
        Time: ${this.hour}:${this.minute.toString().padStart(2, '0')}
        Timezone: UTC${this.timezone >= 0 ? '+' : ''}${this.timezone}
        
        Declination: ${this.declination.toFixed(2)}°
        Hour Angle: ${this.hourAngle.toFixed(2)}°
        Solar Altitude: ${this.solarAltitude.toFixed(2)}°
        Solar Azimuth: ${this.solarAzimuth.toFixed(2)}°
        
        Sun Vector: (${this.VectorSun.x.toFixed(3)}, ${this.VectorSun.y.toFixed(3)}, ${this.VectorSun.z.toFixed(3)})
        Above Horizon: ${this.IsSunAboveHorizon()}`;
	}
}

interface LocationTimeInfo {
	latitude: number;
	longitude: number;
	timezone: string;
	utcOffset: number;
	localTime: Date;
	year: number;
	month: number;
	day: number;
	hour: number;
	minute: number;
	second: number;
}

export class LocationTimeUtility {
	static getTimeFromCoordinatesIntl(lat: number, lng: number): LocationTimeInfo {
		const timezone = this.getTimezoneId(lat, lng);
		const now = new Date();

		const formatter = new Intl.DateTimeFormat('en-US', {
			timeZone: timezone,
			year: 'numeric',
			month: '2-digit',
			day: '2-digit',
			hour: '2-digit',
			minute: '2-digit',
			second: '2-digit',
			hour12: false,
		});

		const parts = formatter.formatToParts(now);
		const year = parseInt(parts.find((p) => p.type === 'year')?.value || '0');
		const month = parseInt(parts.find((p) => p.type === 'month')?.value || '0');
		const day = parseInt(parts.find((p) => p.type === 'day')?.value || '0');
		const hour = parseInt(parts.find((p) => p.type === 'hour')?.value || '0');
		const minute = parseInt(parts.find((p) => p.type === 'minute')?.value || '0');
		const second = parseInt(parts.find((p) => p.type === 'second')?.value || '0');

		const localTime = new Date(year, month - 1, day, hour, minute, second);
		const utcOffset = this.estimateTimezoneOffset(lat, lng);

		return {
			latitude: lat,
			longitude: lng,
			timezone: timezone,
			utcOffset: utcOffset,
			localTime: localTime,
			year: year,
			month: month,
			day: day,
			hour: hour,
			minute: minute,
			second: second,
		};
	}

	private static getTimezoneId(lat: number, lng: number): string {
		const timezones = [
			{ bounds: [33, 43, 124, 132], tz: 'Asia/Seoul' },
			{ bounds: [30, 46, 129, 146], tz: 'Asia/Tokyo' },
			{ bounds: [18, 54, 73, 135], tz: 'Asia/Shanghai' },
			{ bounds: [6, 37, 68, 97], tz: 'Asia/Kolkata' },
			{ bounds: [1, 7, 103, 105], tz: 'Asia/Singapore' },
			{ bounds: [13, 19, 100, 106], tz: 'Asia/Bangkok' },

			{ bounds: [25, 50, -125, -66], tz: 'America/New_York' },
			{ bounds: [25, 50, -105, -90], tz: 'America/Chicago' },
			{ bounds: [25, 50, -125, -105], tz: 'America/Denver' },
			{ bounds: [32, 49, -125, -117], tz: 'America/Los_Angeles' },
			{ bounds: [18, 23, -161, -154], tz: 'Pacific/Honolulu' },

			{ bounds: [49, 61, -8, 2], tz: 'Europe/London' },
			{ bounds: [47, 55, 2, 15], tz: 'Europe/Paris' },
			{ bounds: [55, 70, 10, 32], tz: 'Europe/Stockholm' },
			{ bounds: [35, 47, 12, 30], tz: 'Europe/Rome' },

			{ bounds: [-44, -10, 112, 154], tz: 'Australia/Sydney' },
			{ bounds: [-35, -25, 115, 129], tz: 'Australia/Perth' },
			{ bounds: [-47, -34, 166, 179], tz: 'Pacific/Auckland' },

			{ bounds: [-34, 5, -74, -32], tz: 'America/Sao_Paulo' },
			{ bounds: [-55, -21, -74, -53], tz: 'America/Argentina/Buenos_Aires' },
		];

		for (const zone of timezones) {
			const [minLat, maxLat, minLng, maxLng] = zone.bounds;
			if (lat >= minLat && lat <= maxLat && lng >= minLng && lng <= maxLng) {
				return zone.tz;
			}
		}
		const offset = Math.round(lng / 15);
		if (offset >= 0) {
			return `Etc/GMT-${offset}`;
		} else {
			return `Etc/GMT+${Math.abs(offset)}`;
		}
	}

	private static estimateTimezoneOffset(lat: number, lng: number): number {
		if (lat >= 18 && lat <= 54 && lng >= 73 && lng <= 135) return 8;
		if (lat >= 6 && lat <= 37 && lng >= 68 && lng <= 97) return 5.5;
		if (lat >= -44 && lat <= -10 && lng >= 112 && lng <= 154) {
			if (lng < 127.5) return 8;
			if (lng < 137.5) return 9.5;
			return 10;
		}
		return Math.max(-12, Math.min(14, Math.round(lng / 15)));
	}
}

export const executingAutoSunDirectionTimer = (callback: () => void, debuggerMode = true): (() => void) => {
	const log = (msg: string) => debuggerMode && console.log(msg);

	const now = new Date();
	const msUntilNextMinute = (60 - now.getSeconds()) * 1000 - now.getMilliseconds();

	const timeoutId = setTimeout(() => {
		log('timer executing');
		callback();

		const intervalId = setInterval(() => {
			log('timer executing');
			callback();
		}, 60 * 1000);

		destroy = () => {
			clearTimeout(timeoutId);
			clearInterval(intervalId);
			log('removed the timer!');
		};
	}, msUntilNextMinute);

	let destroy = () => {
		clearTimeout(timeoutId);
		log('removed the timer!');
	};

	return () => destroy();
};
